function App() {
  useEffect(() => {
    console.log("Component mounted");
  }, []);

  return <h1>Hello React</h1>;
}

// [] means the effect runs after the initial mount.

function Counter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    console.log("Component updated");
  }, [count]);

  return (
    <button onClick={() => setCount(count + 1)}>
      {count}
    </button>
  );
}

function Timer() {
  useEffect(() => {
    const id = setInterval(() => {
      console.log("Running...");
    }, 1000);

    return () => {
      clearInterval(id);
      console.log("Timer cleaned up");
    };
  }, []);

  return <h1>Timer</h1>;
}

function User() {
  useEffect(() => {
    console.log("Effect runs after render");

    return () => {
      console.log("Cleanup runs");
    };
  }, []);

  return <h1>User</h1>;
}

useEffect(() => {
  // Runs after the component mounts
  // and when userId changes.
  fetchUser(userId);

  return () => {
    // Cleanup before the effect runs again
    // or when the component unmounts.
    console.log("Cleanup");
  };
}, [userId]);

class User extends React.Component {
  componentDidMount() {
    console.log("Component mounted");
  }

  render() {
    return <h1>User</h1>;
  }
}

class Counter extends React.Component {
  componentDidUpdate(prevProps) {
    if (prevProps.id !== this.props.id) {
      console.log("ID changed");
    }
  }

  render() {
    return <h1>{this.props.id}</h1>;
  }
}

class Timer extends React.Component {
  componentDidMount() {
    this.timer = setInterval(() => {
      console.log("Running");
    }, 1000);
  }

  componentWillUnmount() {
    clearInterval(this.timer);
  }

  render() {
    return <h1>Timer</h1>;
  }
}

function Component({ userId }) {
  useEffect(() => {
    // Similar to mount/update behavior
    console.log("Effect runs", userId);

    return () => {
      // Similar to unmount/cleanup behavior
      console.log("Cleanup");
    };
  }, [userId]);

  return <h1>User: {userId}</h1>;
}
